+func (b *publishTestBroker) PublishWithDeferredConfirmWithContext(ctx context.Context, _, _ string, mandatory, immediate bool, msg amqp.Publishing) (rabbitMQConfirmation, error) {
+	b.publishes.Add(1)
+	if mandatory {
+		b.mandatory.Add(1)
+	}
+	if immediate {
+		b.immediate.Add(1)
+	}
+	if b.publish != nil {
+		return b.publish(ctx, msg)
+	}
+	return nil, nil
+}
+
+func (b *publishTestBroker) ExchangeDeclare(_ string, _ string, _, _, _, _ bool, _ amqp.Table) error {
+	b.declarations.Add(1)
+	if b.declare != nil {
+		return b.declare(false)
+	}
+	return nil
+}
+
+func (b *publishTestBroker) ExchangeDeclarePassive(_ string, _ string, _, _, _, _ bool, _ amqp.Table) error {
+	b.declarations.Add(1)
+	if b.declare != nil {
+		return b.declare(true)
+	}
+	return nil
+}
+
+func (b *publishTestBroker) Confirm(bool) error {
+	if b.confirm != nil {
+		return b.confirm()
+	}
+	return nil
+}
+
+func (b *publishTestBroker) Abort() error {
+	b.aborts.Add(1)
+	if b.abort != nil {
+		b.abort()
+	}
+	return nil
+}
