+func startPublicPublish(r *rabbitMQ, ctx context.Context, topic string) <-chan error {
+	done := make(chan error, 1)
+	go func() { done <- r.Publish(ctx, &pubsub.PublishRequest{Topic: topic}) }()
+	return done
+}
